class StateCore{constructor(e={}){this.state=e,this.listeners=[]}subscribe(e){return this.listeners.push(e),()=>{this.listeners=this.listeners.filter(t=>t!==e)}}setState(e){this.state={...this.state,...e},this.listeners.forEach(e=>e(this.state))}getState(){return this.state}}"undefined"!=typeof module&&module.exports&&(module.exports=StateCore);
